## Manifest 完整接口定义

以下 JSON 与插件包内实际 `manifest.json` 逐字段一致，覆盖插件身份、权限、配置、鉴权、参数、校验、创建、Agent、查询、取消、结果下载、响应和 Agent 响应映射。`documentation` 字段的值就是当前完整文档；为避免文档在自身内部无限递归，JSON 中仅用等义占位文本表示正文。

```json
{
  "apiVersion": "yingce.plugin/v2",
  "id": "grsai-api",
  "name": "Grsai API Media",
  "version": "1.2.3",
  "author": "Grsai / iGO Studio",
  "description": "Grsai 图片与视频异步生成协议插件。",
  "documentation": "<当前插件的完整 documentation，由 README.md 与 docs/interface.md 拼接而成；为避免 JSON 递归，此处不重复展开正文。>",
  "permissions": [
    "generation.run",
    "media.read"
  ],
  "configuration": {
    "fields": [
      {
        "name": "apiKey",
        "type": "secret",
        "label": "API Key",
        "required": true
      }
    ]
  },
  "contributes": {
    "providers": [
      {
        "id": "grsai-minimax-h3",
        "label": "Grsai MiniMax H3 Video",
        "capabilities": [
          "video"
        ],
        "scopes": [
          "admin.system-channel",
          "user.custom-channel",
          "canvas",
          "creation",
          "agent"
        ],
        "baseUrl": "https://grsaiapi.com",
        "auth": {
          "type": "bearer",
          "field": "apiKey"
        },
        "parameters": [
          {
            "name": "model",
            "type": "string",
            "required": true,
            "mapping": "model",
            "description": "视频模型 ID，例如 minimax-h3。"
          },
          {
            "name": "prompt",
            "type": "string",
            "required": true,
            "mapping": "prompt",
            "description": "视频提示词。"
          },
          {
            "name": "images",
            "type": "media[]",
            "required": false,
            "mapping": "images",
            "description": "参考图片 URL 或 Data URL 数组。"
          },
          {
            "name": "audios",
            "type": "media[]",
            "required": false,
            "mapping": "audios",
            "description": "参考音频 URL 或 Data URL 数组。"
          },
          {
            "name": "aspectRatio",
            "type": "string",
            "required": true,
            "mapping": "aspectRatio",
            "description": "统一画布比例；宿主会将其转换为 Grsai 上游支持的 portrait、landscape 或 square。",
            "values": [
              "21:9",
              "16:9",
              "9:16",
              "4:3",
              "3:4",
              "1:1",
              "3:2",
              "2:3"
            ]
          },
          {
            "name": "resolution",
            "type": "string",
            "required": true,
            "mapping": "resolution",
            "description": "分辨率档位，例如 480p。",
            "values": [
              "480p",
              "768p",
              "1080p"
            ]
          },
          {
            "name": "duration",
            "type": "integer",
            "required": true,
            "mapping": "duration",
            "description": "视频时长，单位秒。"
          },
          {
            "name": "providerOptions",
            "type": "object",
            "required": false,
            "mapping": "provider-specific fields",
            "description": "插件命名空间内的厂商扩展字段。"
          }
        ],
        "validations": [
          {
            "assert": {
              "$lte": [
                {
                  "$len": {
                    "$ref": "request.images"
                  }
                },
                9
              ]
            },
            "message": "Grsai MiniMax H3 最多支持 9 张参考图片"
          },
          {
            "assert": {
              "$lte": [
                {
                  "$len": {
                    "$ref": "request.audios"
                  }
                },
                3
              ]
            },
            "message": "Grsai MiniMax H3 最多支持 3 个参考音频"
          },
          {
            "assert": {
              "$in": [
                {
                  "$ref": "request.aspectRatio"
                },
                [
                  "portrait",
                  "landscape",
                  "square"
                ]
              ]
            },
            "message": "Grsai MiniMax H3 aspectRatio 只能是 portrait、landscape 或 square"
          },
          {
            "assert": {
              "$in": [
                {
                  "$ref": "request.resolution"
                },
                [
                  "480p",
                  "768p",
                  "1080p"
                ]
              ]
            },
            "message": "Grsai MiniMax H3 resolution 只能是 480p、768p 或 1080p"
          },
          {
            "assert": {
              "$and": [
                {
                  "$gte": [
                    {
                      "$ref": "request.duration"
                    },
                    1
                  ]
                },
                {
                  "$lte": [
                    {
                      "$ref": "request.duration"
                    },
                    15
                  ]
                }
              ]
            },
            "message": "Grsai MiniMax H3 duration 必须在 1-15 秒之间"
          },
          {
            "assert": {
              "$or": [
                {
                  "$ne": [
                    {
                      "$ref": "request.resolution"
                    },
                    "1080p"
                  ]
                },
                {
                  "$lte": [
                    {
                      "$ref": "request.duration"
                    },
                    10
                  ]
                }
              ]
            },
            "message": "Grsai MiniMax H3 使用 1080p 时 duration 最多 10 秒"
          }
        ],
        "create": {
          "method": "POST",
          "path": "/v1/api/generate",
          "contentType": "application/json",
          "body": {
            "prompt": {
              "$ref": "request.prompt"
            },
            "aspectRatio": {
              "$omitEmpty": {
                "$ref": "request.aspectRatio"
              }
            },
            "images": {
              "$omitEmpty": {
                "$map": {
                  "from": {
                    "$sortByOrder": {
                      "$ref": "request.images"
                    }
                  },
                  "as": "media",
                  "in": {
                    "$ref": "media.value"
                  }
                }
              }
            },
            "audios": {
              "$omitEmpty": {
                "$map": {
                  "from": {
                    "$sortByOrder": {
                      "$ref": "request.audios"
                    }
                  },
                  "as": "media",
                  "in": {
                    "$ref": "media.value"
                  }
                }
              }
            },
            "seed": {
              "$omitEmpty": {
                "$ref": "request.providerOptions.grsai-minimax-h3.seed"
              }
            },
            "resolution": {
              "$omitEmpty": {
                "$ref": "request.resolution"
              }
            },
            "model": {
              "$ref": "request.model"
            },
            "duration": {
              "$omitEmpty": {
                "$ref": "request.duration"
              }
            },
            "replyType": {
              "$coalesce": [
                {
                  "$ref": "request.providerOptions.grsai-minimax-h3.replyType"
                },
                "async"
              ]
            }
          }
        },
        "poll": {
          "method": "GET",
          "path": "/v1/api/result",
          "query": {
            "id": {
              "$ref": "taskId"
            }
          }
        },
        "response": {
          "taskId": {
            "$coalesce": [
              {
                "$ref": "response.id"
              },
              {
                "$ref": "response.task_id"
              },
              {
                "$ref": "response.taskId"
              },
              {
                "$ref": "response.data.id"
              },
              {
                "$ref": "taskId"
              }
            ]
          },
          "status": {
            "$coalesce": [
              {
                "$ref": "response.status"
              },
              {
                "$ref": "response.state"
              },
              {
                "$ref": "response.data.status"
              },
              "pending"
            ]
          },
          "message": {
            "$coalesce": [
              {
                "$ref": "response.error"
              },
              {
                "$ref": "response.error.message"
              },
              {
                "$ref": "response.message"
              },
              {
                "$ref": "response.fail_reason"
              }
            ]
          },
          "videos": {
            "$coalesce": [
              {
                "$map": {
                  "from": {
                    "$ref": "response.results"
                  },
                  "as": "result",
                  "in": {
                    "$ref": "result.url"
                  }
                }
              },
              {
                "$ref": "response.video_url"
              },
              {
                "$ref": "response.videoUrl"
              },
              {
                "$ref": "response.result_url"
              },
              {
                "$ref": "response.url"
              }
            ]
          },
          "errorPaths": [
            "error",
            "error.code"
          ],
          "resultEphemeral": true
        },
        "nonCancelable": {
          "reason": "当前协议 profile 未提供可验证的上游取消端点；宿主只能停止后续轮询，不能宣称上游任务已取消。"
        }
      },
      {
        "id": "grsai-nano-banana-image",
        "label": "Grsai Nano Banana Image",
        "capabilities": [
          "image"
        ],
        "scopes": [
          "admin.system-channel",
          "user.custom-channel",
          "canvas",
          "creation",
          "agent"
        ],
        "baseUrl": "https://grsaiapi.com",
        "auth": {
          "type": "bearer",
          "field": "apiKey"
        },
        "parameters": [
          {
            "name": "model",
            "type": "string",
            "required": true,
            "mapping": "model",
            "description": "图片模型 ID，例如 nano-banana-2。"
          },
          {
            "name": "prompt",
            "type": "string",
            "required": true,
            "mapping": "prompt",
            "description": "图片提示词。"
          },
          {
            "name": "images",
            "type": "media[]",
            "required": false,
            "mapping": "images",
            "description": "参考图片 URL 或 Data URL 数组。"
          },
          {
            "name": "aspectRatio",
            "type": "string",
            "required": false,
            "mapping": "aspectRatio",
            "description": "画幅比例，例如 1:1。"
          },
          {
            "name": "resolution",
            "type": "string",
            "required": false,
            "mapping": "imageSize",
            "description": "图片尺寸档位，例如 1K。",
            "values": [
              "1K",
              "2K",
              "4K"
            ]
          },
          {
            "name": "quality",
            "type": "string",
            "required": false,
            "mapping": "imageSize",
            "description": "统一图片分辨率档位；1k/low、2k/medium、4k/high 会规范化为上游要求的 1K、2K、4K。"
          },
          {
            "name": "providerOptions",
            "type": "object",
            "required": false,
            "mapping": "provider-specific fields",
            "description": "插件命名空间内的厂商扩展字段。"
          }
        ],
        "create": {
          "method": "POST",
          "path": "/v1/api/generate",
          "contentType": "application/json",
          "body": {
            "model": {
              "$ref": "request.model"
            },
            "prompt": {
              "$ref": "request.prompt"
            },
            "images": {
              "$map": {
                "from": {
                  "$filter": {
                    "from": {
                      "$sortByOrder": {
                        "$ref": "request.images"
                      }
                    },
                    "as": "media",
                    "where": {
                      "$ne": [
                        {
                          "$ref": "media.role"
                        },
                        "mask"
                      ]
                    }
                  }
                },
                "as": "media",
                "in": {
                  "$ref": "media.value"
                }
              }
            },
            "aspectRatio": {
              "$omitEmpty": {
                "$ref": "request.aspectRatio"
              }
            },
            "imageSize": {
              "$omitEmpty": {
                "$coalesce": [
                  {
                    "$ref": "request.providerOptions.grsai-nano-banana-image.imageSize"
                  },
                  {
                    "$switch": {
                      "cases": [
                        {
                          "when": {
                            "$in": [
                              {
                                "$lower": {
                                  "$ref": "request.quality"
                                }
                              },
                              [
                                "1k",
                                "low"
                              ]
                            ]
                          },
                          "then": "1K"
                        },
                        {
                          "when": {
                            "$in": [
                              {
                                "$lower": {
                                  "$ref": "request.quality"
                                }
                              },
                              [
                                "2k",
                                "medium"
                              ]
                            ]
                          },
                          "then": "2K"
